-- Keep per-resource cursors out of source_state's bounded metric-label set.
ALTER TABLE event_fetch ADD COLUMN adapter_cursor text CHECK(octet_length(adapter_cursor)<=4096);

-- Reclassify existing routing hints without changing identities, documents or references.
-- Snapshot of the shipped host/path registry; future registries use later migrations.
WITH registry AS (
 SELECT * FROM jsonb_to_recordset($registry$[{"domains":["portal.einundzwanzig.space"],"paths":[]},{"domains":["api.btcmap.org"],"paths":["/v4/events"]},{"domains":["flockstr.com","njump.me","nostr.at","honey.hivetalk.org","letsmiti.app"],"paths":[]},{"domains":["calendar.google.com"],"paths":[]},{"domains":["icloud.com"],"paths":[]},{"domains":["outlook.office365.com","outlook.live.com"],"paths":[]},{"domains":["nch.nerdraum.de"],"paths":[]},{"domains":["calendar.proton.me"],"paths":[]},{"domains":["luma.com","lu.ma"],"paths":[]},{"domains":["meetup.com"],"paths":[]},{"domains":["eventbrite.com","eventbrite.co.uk","eventbrite.de","eventbrite.ch"],"paths":[]},{"domains":["partiful.com"],"paths":[]},{"domains":["posh.vip"],"paths":[]},{"domains":["events.ringcentral.com","app.events.ringcentral.com","app.hopin.com"],"paths":[]},{"domains":["airmeet.com","api.airmeet.com"],"paths":[]},{"domains":["mobilizon.fr","keskonfai.fr"],"paths":[]},{"domains":["demo.gancio.org"],"paths":[]},{"domains":["events.sfconservancy.org","gath.io"],"paths":[]},{"domains":["wikidata.org","wikipedia.org"],"paths":[]},{"domains":["ti.to"],"paths":[]},{"domains":["petzi.ch"],"paths":[]},{"domains":["my.weezevent.com","api.weezevent.com"],"paths":[]},{"domains":["pretix.eu"],"paths":[]},{"domains":["eventyay.com","tickets.eventyay.com"],"paths":[]},{"domains":["guidle.com"],"paths":[]},{"domains":["eventfrog.ch","eventfrog.de"],"paths":[]},{"domains":["allevents.in"],"paths":[]},{"domains":["billetto.co.uk","billetto.dk","billetto.se"],"paths":[]},{"domains":["fatsoma.com"],"paths":[]},{"domains":["designmynight.com"],"paths":[]},{"domains":["rausgegangen.de"],"paths":[]},{"domains":["fixr.co"],"paths":[]},{"domains":["wegow.com"],"paths":[]},{"domains":["stager.co"],"paths":[]},{"domains":["reservix.de","adticket.de"],"paths":[]},{"domains":["entradium.com"],"paths":[]},{"domains":["starticket.ch"],"paths":[]},{"domains":["songkick.com"],"paths":[]},{"domains":["humanitix.com"],"paths":[]},{"domains":["infomaniak.events"],"paths":[]},{"domains":["xceed.me"],"paths":[]},{"domains":["ents24.com"],"paths":[]},{"domains":["ticketino.com"],"paths":[]},{"domains":["dice.fm"],"paths":[]},{"domains":["feverup.com"],"paths":[]},{"domains":["ticketmaster.com","ticketmaster.co.uk","ticketmaster.de","ticketmaster.ch"],"paths":[]},{"domains":["skiddle.com"],"paths":[]},{"domains":["ra.co"],"paths":[]},{"domains":["facebook.com","fb.me"],"paths":[]},{"domains":["eventim.de","eventim.ch","eventim.co.uk","ticketcorner.ch","ticketone.it","oeticket.com","seetickets.com","eventim-light.com","paylogic.com"],"paths":[]},{"domains":["shotgun.live"],"paths":[]},{"domains":["bandsintown.com"],"paths":[]},{"domains":["vivaticket.com"],"paths":[]},{"domains":["fourvenues.com"],"paths":[]},{"domains":["zoom.us","zoom.com","meet.google.com","teams.microsoft.com","teams.live.com"],"paths":[]},{"domains":["lemonade.social"],"paths":[]},{"domains":["weeztix.com","ticketkantoor.nl"],"paths":[]}]$registry$::jsonb) AS d(domains text[],paths text[])
), candidates AS (
 SELECT r.id FROM resource r WHERE (r.resolver IN ('web','event') OR r.resolver IS NULL) AND (
 r.scheme='nostr' OR (r.scheme IN ('http','https','webcal','webcals') AND (
 EXISTS(SELECT 1 FROM registry d, unnest(d.domains) h WHERE
 (lower(rtrim(r.host,'.'))=h OR lower(rtrim(r.host,'.')) LIKE '%.'||h)
 AND (cardinality(d.paths)=0 OR EXISTS(SELECT 1 FROM unnest(d.paths) p WHERE regexp_replace(r.uri,'^[^:]+://[^/]+','') LIKE p||'%')))
 OR r.uri ~ '/(remote[.]php/dav/public-calendars/|apps/calendar/(p|embed)/)'
 OR lower(rtrim(r.host,'.')) IN ('api.nostr.wine','api.billetto.com','api.eventfrog.net')
 OR (lower(rtrim(r.host,'.'))='www.googleapis.com' AND r.uri LIKE '%/calendar/v3/calendars/%')
 OR r.uri LIKE '%/starticket/wwwroot/ticketing/feeds/starticketfeed_D.xml'
 )))
)
UPDATE resource r SET resolver='event_platform',final=false,dead_letter=false,attempts=0,next_attempt_at=now()
 FROM candidates c WHERE r.id=c.id;
